// Wait past the frame already queued when annotations are hidden. A timeout must
// never authorize recognition of the stale, annotated frame.
export function waitForCaptureFrame(video,timeoutMs=1200){
 if(!video.requestVideoFrameCallback)return Promise.resolve(false);
 return new Promise(resolve=>{let handle;const timer=setTimeout(()=>{video.cancelVideoFrameCallback(handle);resolve(false);},timeoutMs);handle=video.requestVideoFrameCallback(()=>{handle=video.requestVideoFrameCallback(()=>{clearTimeout(timer);resolve(true);});});});
}
// Native thumbnails omit the system cursor; reconcile their colour profile with the live stream.
export async function cleanCapture(api,sourceId,frame,isCancelled=()=>false){const reference=document.createElement('canvas');reference.width=128;reference.height=128;const rc=reference.getContext('2d',{willReadFrequently:true});rc.drawImage(frame,0,0,128,128);const before=rc.getImageData(0,0,128,128).data;const data=await api.captureStill(sourceId,frame.width,frame.height);if(isCancelled())return false;const image=new Image();image.src=data;await image.decode();if(isCancelled())return false;rc.drawImage(image,0,0,128,128);const after=rc.getImageData(0,0,128,128).data;let visible=0;for(let i=0;i<after.length;i+=4)if(Math.max(after[i],after[i+1],after[i+2])>35)visible++;if(visible<after.length/400)return false;const bins=Array.from({length:3},()=>Array.from({length:256},()=>[]));for(let i=0;i<before.length;i+=4)for(let c=0;c<3;c++)bins[c][after[i+c]].push(before[i+c]);const lut=bins.map(channel=>{const values=channel.map(samples=>samples.length>=3?samples.sort((a,b)=>a-b)[samples.length>>1]:null);for(let i=0;i<256;i++)if(values[i]===null){let a=i-1,b=i+1;while(a>=0&&values[a]===null)a--;while(b<256&&values[b]===null)b++;values[i]=a>=0&&b<256?Math.round(values[a]+(values[b]-values[a])*(i-a)/(b-a)):a>=0?values[a]:b<256?values[b]:i;}return values;});const fc=frame.getContext('2d',{willReadFrequently:true});fc.drawImage(image,0,0,frame.width,frame.height);const pixels=fc.getImageData(0,0,frame.width,frame.height);for(let i=0;i<pixels.data.length;i+=4)for(let c=0;c<3;c++)pixels.data[i+c]=lut[c][pixels.data[i+c]];fc.putImageData(pixels,0,0);return true;}
